import Foundation

public protocol NodeService { func run(argv:[String],cwd:String,env:[String:String],stdinFD:Int32,stdoutFD:Int32,stderrFD:Int32,interactive:Bool) async -> Int32; func interrupt() }
public final class LocalNodeService: NodeService { private var process: Process?; public init() {} public func run(argv:[String],cwd:String,env:[String:String],stdinFD:Int32,stdoutFD:Int32,stderrFD:Int32,interactive:Bool) async -> Int32 { #if os(iOS) return 126 #else guard !argv.isEmpty else{return 2}; let p=Process(); p.executableURL=URL(fileURLWithPath:"/usr/bin/env"); p.arguments=["node"]+argv; p.currentDirectoryURL=URL(fileURLWithPath:cwd); p.environment=env; process=p; do { try p.run(); p.waitUntilExit(); return p.terminationStatus } catch{return 127} #endif } public func interrupt(){ process?.interrupt() } }
public final class PythonRuntime { public init() {} public func run(arguments:[String],cwd:String,env:[String:String]) async -> Int32 { #if os(iOS) return 126 #else let p=Process(); p.executableURL=URL(fileURLWithPath:"/usr/bin/env"); p.arguments=["python3"]+arguments; p.currentDirectoryURL=URL(fileURLWithPath:cwd); p.environment=env; do{try p.run();p.waitUntilExit();return p.terminationStatus}catch{return 127} #endif } }
public final class ClaudeLauncher { private let node: NodeService; public init(node:NodeService=LocalNodeService()){self.node=node} public func launch(arguments:[String],cwd:String,env:[String:String],stdinFD:Int32=-1,stdoutFD:Int32=-1,stderrFD:Int32=-1,interactive:Bool=true) async -> Int32 { await node.run(argv:["claude"]+arguments,cwd:cwd,env:env,stdinFD:stdinFD,stdoutFD:stdoutFD,stderrFD:stderrFD,interactive:interactive) } }
public final class LinuxLane { public enum State { case unavailable, ready }; public private(set) var state:State = .unavailable; public init() {} public func bootstrap() async throws { throw NSError(domain:"TermXLinux",code:1,userInfo:[NSLocalizedDescriptionKey:"Linux compatibility lane requires the Blink xcframework and an app-bundled rootfs; attach those artifacts in Xcode before enabling it."]) } public func run(arguments:[String],cwd:String) async -> Int32 { 126 } }
